INSERT INTO `texts` (`key`, `title`, `content`, `active`) VALUES
('msg_trial_day1', 'Триал День 1: Питание', 'Привет 👀\nдавай сегодня направим фокус на твое питание?\n\nВсе, что ты ешь сегодня это реально даёт тебе энергию или наоборот сливает?\n\nскинь фото своей тарелки 👇 я разберу по макроэлементам и скажу, где ты теряешь ресурс', 1),
('msg_trial_day2', 'Триал День 2: Кожа', 'Привет привет! Сегодня направим фокус на кожу и сияние:\n\nТы знаешь что ты наносишь на свое лицо?\n90% того, что нам рекомендуют либо не работает либо делает хуже\n\nхочешь проверить свои средства?\nскинь фото крема или состав 👇 я скажу:\n— что в нём реально работает\n— а что просто маркетинг', 1),
('msg_trial_day3', 'Триал День 3: Система', 'Ты уже попробовала пару функций и, скорее всего, заметила разницу\nно есть нюанс:\n\nотдельные разборы — это не результат\nрезультат даёт система\n\nдавай соберу тебе мини-день под твоё состояние 👇', 1),
('msg_trial_day4', 'Триал День 4: Оффер', 'Смотри, как это обычно происходит:\nдевочки пробуют 1-2 функции\nвидят, что это работает\nно дальше возвращаются в хаос\nпотому что нет системы\n\nв полной версии я как раз собираю тебе это под тебя:\n— питание\n— уход\n— ритм\n— состояние\n\nчтобы ты не начинала заново', 1),
('msg_after_demo_followup', 'После демо: Фоллоу-ап', 'слушай, как тебе формат с промптом? 👀\n\nполучилось настроить или пока не очень?\n\nесли честно, в одиночку это часто чуть сложнее, чем кажется\n\nпоэтому если захочешь,\nможно собрать это вместе и сразу под тебя\n\nя рядом 🤍', 1),
('msg_return_offer', 'Возврат: Оффер', 'слушай, ты уже попробовала этот формат 👀\n\nи ты видишь, что это не просто «поболтать»\n\nесли хочешь реально выстроить систему и не откатываться назад\nможно сделать это вместе\n\nили подключить полный доступ к боту\n\nя рядом 🤍', 1),
('msg_return_day_3', 'Возврат: День 3', 'слушай, вспомнила про тебя 👀\n\nкак ты сейчас по состоянию?\n\nполучается держать то, что мы начали\nили уже немного “съехало”?\n\nэто нормально, если что\nпросто напиши, как есть 🤍', 1),
('msg_return_day_5', 'Возврат: День 5', 'знаешь, что я часто вижу 👀\n\nдевочки начинают\nчуть чувствуют изменения\nи потом снова откатываются\n\nне потому что слабые\nа потому что нет системы\n\nи вот это как раз то, что мы собираем\n\nесли чувствуешь, что снова теряешься\nможно вернуться и сделать это нормально 🤍', 1),
('btn_trial_send_photo', 'Кнопка: Отправить фото', '📸 Отправить фото', 1),
('btn_trial_check_cosmetics', 'Кнопка: Разобрать средство', '🧴 Разобрать средство', 1),
('btn_trial_build_day', 'Кнопка: Собрать мой день', '🥗 Собрать мой день', 1),
('btn_trial_full_version', 'Кнопка: Хочу полную версию', '💎 Хочу полную версию', 1)
